def porphyrin(cx, cy, fill, metal, side_o=False):
    import math
    pts = ' '.join(f'{cx + 70*math.cos(math.radians(22.5 + 45*k)):.0f},{cy + 70*math.sin(math.radians(22.5 + 45*k)):.0f}' for k in range(8))
    b = [f'<polygon points="{pts}" fill="{fill}"/>', txt(cx, cy + 5, metal, 14, 'middle', 'bold', '#fff')]
    for dx, dy in ((-22, -22), (22, -22), (-22, 22), (22, 22)):
        b.append(txt(cx + dx, cy + dy + 4, 'N', 11, 'middle', 'bold', '#fff'))
    b.append(f'<path d="M{cx-25},{cy+70} v20 M{cx+25},{cy+70} v20" stroke="#333" stroke-width="2"/>' + txt(cx - 35, cy + 110, 'C=O', 11, 'middle') + txt(cx + 35, cy + 110, 'C=O', 11, 'middle'))
    b.append(txt(cx - 35, cy + 125, 'OH', 11, 'middle') + txt(cx + 35, cy + 125, 'OH' if not side_o else 'O-C₂₀', 11, 'middle'))
    return ''.join(b)


def hb_chl(L):
    b = [porphyrin(110, 100, '#ef5350', 'Fe'), porphyrin(330, 100, '#43a047', 'Mg', True)]
    b.append(txt(110, 255, L['hb'], 13, 'middle', 'bold') + txt(330, 255, L['chl'], 13, 'middle', 'bold'))
    return svg_wrap(''.join(b), 440, 270, L['title'])


